contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address logBefore, address logAfter) public {
        // Precondition: ensure the two addresses are distinct so the rule is nontrivial
        require(logBefore != logAfter);

        // Fresh contract: not initialized yet.
        // SetLogFile(logBefore) must succeed on fresh contract.
        c.SetLogFile(logBefore);

        // Now mark initialized.
        c.Initialized();

        // Attempt to change LogFile to logAfter. This must revert because intitalized is true.
        bool reverted;
        try c.SetLogFile(logAfter) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: after Initialized(), SetLogFile reverts for ANY address argument.
        // We cannot read LogFile directly (no public getter), but the revert flag is the observable effect.
        assert(reverted);
    }
}

